p rectangle in pixels.","type":"integer","format":"uint32","minimum":0},"height":{"description":"Height of the crop rectangle in pixels.","type":"integer","format":"uint32","minimum":0}},"required":["x","y","width","height"]}}},"strict":false}},{"type":"function","function":{"name":"shell","description":"Execute a shell command in the current dir. Commands run under `bash` (set GOOSE_SHELL to override) - write command strings in that shell's syntax. Returns an object with stdout and stderr as separate fields. The output of each stream is limited to up to 2000 lines, and longer outputs will be saved to a temporary file.","parameters":{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"ShellParams","type":"object","properties":{"command":{"type":"string"},"timeout_secs":{"description":"Maximum time in seconds to allow the command to run before it is killed.\nIf omitted, defaults to DEFAULT_EXTENSION_TIMEOUT.","type":"integer","format":"uint64","minimum":0,"default":null}},"required":["command"]},"strict":false}},{"type":"function","function":{"name":"tree","description":"List a directory tree with line counts. Traversal respects .gitignore rules.","parameters":{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"TreeParams","type":"object","properties":{"path":{"type":"string"},"depth":{"type":"integer","format":"uint32","minimum":0,"default":2}},"required":["path"]},"strict":false}},{"type":"function","function":{"name":"write","description":"Create a new file or overwrite an existing file. Creates parent directories if needed.","parameters":{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"FileWriteParams","type":"object","properties":{"path":{"type":"string"},"content":{"type":"string"}},"required":["path","content"]},"strict":false}}],"stream":true,"stream_options":{"include_usage":true}}}
